from pathlib import Path
from playwright.sync_api import sync_playwright
import json, re, traceback, math
root=Path(__file__).resolve().parent.parent
project=json.loads((root/'project.json').read_text())
artifact=root.parent/(project['slug']+'.html')
results=[]

def check(name,condition,detail=''):
    results.append({'name':name,'pass':bool(condition),'error':str(detail) if not condition else ''})

def scenario(name,fn):
    try: fn()
    except Exception as e: check(name,False,traceback.format_exc())

pad_init='''window.__pads=[];Object.defineProperty(navigator,'getGamepads',{value:()=>window.__pads});window.makePad=(i)=>({id:'DualSense standard test controller',index:i,mapping:'standard',connected:true,axes:[0,0,0,0],buttons:Array.from({length:17},()=>({pressed:false,touched:false,value:0})),timestamp:1});'''
with sync_playwright() as pw:
    browser=pw.chromium.launch()
    context=browser.new_context(viewport={'width':1920,'height':1080})
    context.add_init_script(pad_init)
    page=context.new_page(); errors=[]
    page.on('pageerror',lambda e:errors.append(str(e)))
    page.on('console',lambda m:errors.append(m.text) if m.type=='error' else None)
    def boot():
        page.goto(artifact.as_uri());page.wait_for_function('window.__game && __game.sceneName === "title"');page.wait_for_timeout(320)
    def start(opts=None):
        page.evaluate('(o)=>{__edge.startRun(o||{});__game.stop();__game.advance(.05);}',opts)
    def snapshot(): return page.evaluate('__game.debug.snapshot()')
    def advance(seconds): page.evaluate('(s)=>__game.advance(s,{draw:true})',seconds)
    def press_pad(button):
        page.evaluate('(b)=>{__pads[0].buttons[b]={pressed:true,value:1,touched:true};__game.advance(.04);__pads[0].buttons[b]={pressed:false,value:0,touched:false};__game.advance(.04)}',button)
    def desktop():
        boot()
        check('packaged file boots with the correct title',page.title()=='Yars on the Edge')
        check('first launch uses ten percent music and PlayStation glyphs',page.evaluate('__game.settings.music===.1 && __game.settings.glyphs==="playstation"'))
        check('boot:false clears the engine boot flag',page.evaluate('__game._booting===false'))
        bounds=page.get_by_role('button',name='About / Credits',exact=True).bounding_box()
        check('all title actions fit the TV viewport',bounds['y']+bounds['height']<1080,bounds)
        page.evaluate('__game.advance(0,{draw:true})');page.screenshot(animations='disabled',path=str(root/'tests/artifacts/title.png'))
        page.get_by_role('button',name='Solo campaign',exact=True).click()
        page.wait_for_function('__game.sceneName === "play" && __edge.world.tick>5')
        check('native title click enters actual gameplay',page.evaluate('__edge.world.status==="playing" && __game.sceneName==="play"'))
        page.evaluate('__game.stop()')
        before=page.evaluate('__edge.world.players[0].x')
        page.keyboard.down('d');advance(.5);page.keyboard.up('d');advance(.02)
        check('keyboard movement is immediate and native',page.evaluate('__edge.world.players[0].x')>before+40)
        page.mouse.move(1700,500);page.mouse.down();advance(.4);page.mouse.up();advance(.01)
        check('mouse aims independently and held fire emits primary shots',page.evaluate('__edge.world.stats.shots>0 && __edge.world.players[0].ax>.8'))
        check('meaningful mouse motion switches prompt family',page.evaluate('__game.input.lastDevice==="mouse"'))
        page.keyboard.press('Escape');advance(.04)
        check('Escape opens native pause with Dev reachable',page.evaluate('__game.paused && __edge.ui.screen==="pause"') and page.get_by_role('button',name='Dev workbench',exact=True).count()==1)
        tick=page.evaluate('__edge.world.tick');advance(.3)
        check('standalone pause holds simulation tick',page.evaluate('__edge.world.tick')==tick)
        page.get_by_role('button',name='Dev workbench',exact=True).click()
        check('workbench opens from the pause menu',page.evaluate('__edge.ui.screen==="dev"'))
        page.get_by_role('button',name='Live balance',exact=True).click()
        slider=page.get_by_role('slider',name='Scout speed',exact=True)
        slider.fill('150');slider.dispatch_event('input')
        check('live tuning is pending until a fixed boundary',page.evaluate('__edge.world.tuning.speed===116 && __edge.world.pendingTuning.speed===150'))
        page.get_by_role('button',name='Apply & return to play',exact=True).click();advance(.03)
        check('live tuning applies and marks practice',page.evaluate('__edge.world.tuning.speed===150 && __edge.world.practice'))
        page.evaluate('__game.pause();__game.advance(.03);__edge.dev.show();__edge.dev.balance()')
        page.get_by_role('button',name='Reset to defaults',exact=True).click()
        page.get_by_role('button',name='Apply & return to play',exact=True).click();advance(.03)
        check('Reset to defaults restores real balance values',page.evaluate('__edge.world.tuning.speed===116 && __edge.world.tuning.charge===5'))
        page.evaluate('__edge.dev.freeze=true')
        tick=page.evaluate('__edge.world.tick');advance(.2)
        check('freeze holds the simulation while UI input still ticks',page.evaluate('__edge.world.tick')==tick)
        page.evaluate('__game.pause();__game.advance(.02);__edge.dev.show()')
        page.get_by_role('button',name='Step one tick',exact=True).click()
        check('single step advances exactly one frozen tick',page.evaluate('__edge.world.tick')==tick+1)
        page.evaluate('__edge.dev.editor()')
        check('controller-compatible editor exposes cursor and path sliders',page.get_by_role('slider',name='Cell column',exact=True).count()==1 and page.get_by_role('slider',name='Plate period',exact=True).count()==1)
        roundtrip=page.evaluate('''()=>{const d=__edge.dev;d.encounter=Edge.encounterOf(0);__game.settings.set('editCol',2);__game.settings.set('editRow',7);d.paint(2,7,false);const s=JSON.stringify(d.export());const b=d.import(s);return JSON.stringify(b)===s}''')
        check('editor JSON export and reload round-trip exactly',roundtrip)
        invalid=page.evaluate('''()=>{try{__edge.dev.import('{"schema":7}');return false}catch{return true}}''')
        check('editor rejects invalid schema without changing the encounter',invalid)
        page.evaluate('__edge.dev.jsonScreen()')
        check('JSON import/export has real editable text',len(page.get_by_role('textbox',name='Encounter JSON').input_value())>100)
        page.evaluate('__edge.ui.hide();__edge.dev.freeze=false;__game.pause();__game.advance(.03);__game.menu("controls")')
        page.get_by_role('button',name=re.compile('Primary stream, keyboard:')).click()
        page.keyboard.press('q');advance(.03)
        check('native controls rebind primary fire',page.evaluate('__game.input.map.fire.includes("KeyQ")'))
        page.evaluate('__edge.ui.hide();__game.resume()');page.keyboard.down('q');advance(.2);page.keyboard.up('q');advance(.01)
        check('rebound key drives the same fire action',page.evaluate('__edge.world.stats.shots>2'))
        page.evaluate('__game.input.resetBindings();__game.settings.set("music",.27)')
        page.reload();page.wait_for_function('window.__game');page.wait_for_timeout(150)
        check('returning-user music selection survives reload',page.evaluate('__game.settings.music===.27'))
        page.evaluate('__game.settings.set("music",.1)')
    scenario('desktop UI/input workflow',desktop)

    def gamepads():
        boot();page.evaluate('__game.stop();__pads=[makePad(0)]')
        press_pad(0);advance(.1)
        check('standard-mapping Cross starts the focused title action',page.evaluate('__game.sceneName==="play"'))
        x=page.evaluate('__edge.world.players[0].x')
        page.evaluate('__pads[0].axes[0]=1;__pads[0].axes[2]=1;__pads[0].buttons[7]={pressed:true,value:1};__game.advance(.5);__pads[0].axes=[0,0,0,0];__pads[0].buttons[7]={pressed:false,value:0};__game.advance(.02)')
        check('left/right sticks and R2 move, aim and fire',page.evaluate('__edge.world.players[0].x')>x+40 and page.evaluate('__edge.world.stats.shots')>0)
        check('pad actions show PlayStation R2/L2',page.evaluate('__game.input.lastDevice==="gamepad" && /R2/.test(__game.input.label("fire")) && /L2/.test(__game.input.label("cannon"))'))
        page.evaluate('__game.settings.set("glyphs","xbox")')
        check('Xbox glyph setting updates labels',page.evaluate('/RT/.test(__game.input.label("fire")) && /LT/.test(__game.input.label("cannon"))'))
        page.evaluate('__pads[0].buttons[8]={pressed:true,value:1};__pads[0].buttons[9]={pressed:true,value:1};__game.advance(.04)')
        check('Create plus Options remains reserved for the hub',page.evaluate('!__game.paused'))
        page.evaluate('__pads[0].buttons[8]={pressed:false,value:0};__pads[0].buttons[9]={pressed:false,value:0};__game.advance(.04)')
        press_pad(9);check('Options pauses and Circle backs through native menus',page.evaluate('__game.paused'))
        for _ in range(12):
            if page.evaluate('document.activeElement.textContent')=='Dev workbench':break
            press_pad(13)
        press_pad(0)
        check('controller can navigate from native pause into the workbench',page.evaluate('__edge.ui.screen==="dev"'))
        press_pad(1);press_pad(1);check('Circle resumes from the nested workbench and pause',page.evaluate('!__game.paused && !__edge.ui.screen'))
        page.evaluate('__pads[0].axes[0]=.1;__game.advance(.2)')
        check('deadzone suppresses stick drift',page.evaluate('Math.abs(__edge.world.players[0].vx)<.1'))
        page.evaluate('__pads=[];__game.advance(.04)')
        check('controller disconnection pauses standalone',page.evaluate('__game.paused && __game.pauseReason==="controller"'))
        page.evaluate('__pads=[makePad(0)];__game.advance(.04)');press_pad(1)
        check('controller reconnect can resume',page.evaluate('!__game.paused'))
        page.evaluate('__game.settings.set("glyphs","playstation");__pads=[makePad(0),makePad(1)]')
        start({'coop':True});x=page.evaluate('__edge.world.players.map(p=>p.x)')
        page.evaluate('__pads[0].axes[0]=1;__pads[1].axes[1]=1;__game.advance(.4);__pads[0].axes=[0,0,0,0];__pads[1].axes=[0,0,0,0]')
        positions=page.evaluate('__edge.world.players.map(p=>[p.x,p.y])')
        check('two controllers drive different scouts',positions[0][0]>x[0]+25 and abs(positions[1][0]-x[1])<2,positions)
        page.evaluate('__game.advance(0,{draw:true})');page.screenshot(animations='disabled',path=str(root/'tests/artifacts/co-op.png'))
        page.evaluate('__pads=[makePad(0)]');start({'coop':True})
        check('keyboard plus one pad assigns each device once',page.evaluate('__game.players[0].pad===null && __game.players[1].pad===0'))
        page.evaluate('__edge.world.players[1].charge=5;__edge.syncPresentation(.01);__game.advance(.02,{draw:true})')
        check('mixed-device co-op shows each scout its own siege button without a false disconnect pause',page.evaluate('!__game.paused&&document.querySelectorAll(".scout span")[1].textContent.includes("L2")&&__game.players[0].lastDevice==="keyboard"'))
        page.evaluate('__pads=[]');start({'coop':True})
        page.keyboard.down('d');page.keyboard.down('ArrowDown');advance(.4);page.keyboard.up('d');page.keyboard.up('ArrowDown')
        check('shared-keyboard co-op supports independent movement',page.evaluate('__edge.world.players[0].x>120 && __edge.world.players[1].y>190'))
    scenario('controller and local co-op workflow',gamepads)

    def geometry_and_attract():
        boot();page.evaluate('__game.stop();__edge.controls.lastActivity=__game.real');advance(9.7)
        check('attract does not start before ten idle seconds',page.evaluate('!__edge.attract'))
        advance(.5)
        check('attract starts after ten idle seconds',page.evaluate('__edge.attract && __game.sceneName==="play" && __edge.world.demo'))
        before=page.evaluate('JSON.stringify({r:__edge.records,u:__edge.unlocked})')
        page.evaluate('''()=>{const a=__edge;const w=a.world;for(let i=0;i<120*100;i++)w.step(a.pilot.actions(w));a.syncPresentation(.1)}''')
        check('attract pilot demonstrates bite/cannon/airborne/refill/reflection',page.evaluate('__edge.world.lessons.bitten && __edge.world.lessons.called && __edge.world.lessons.intercept && __edge.world.lessons.refill && __edge.world.stats.reflections>0'))
        page.evaluate('__game.advance(6,{draw:true})')
        check('attract loops into a fresh isolated world',page.evaluate('__edge.attract && __edge.world.tick<600 && !__edge.world.outcome'))
        page.keyboard.press('Enter');advance(.1)
        check('attract exit key is consumed and returns to title',page.evaluate('__game.sceneName==="title" && !__edge.attract && !__edge.world'))
        check('attract never changes records or unlocks',before==page.evaluate('JSON.stringify({r:__edge.records,u:__edge.unlocked})'))
        page.evaluate('__edge.startAttract();__game.advance(.1)');page.mouse.move(600,400);advance(.1)
        check('meaningful pointer movement exits attract',page.evaluate('__game.sceneName==="title" && !__edge.attract'))
        page.evaluate('__edge.startAttract();__game.advance(.1);__pads=[makePad(0)];__pads[0].buttons[0]={pressed:true,value:1};__game.advance(.2)')
        check('pad activity exits attract without starting a campaign',page.evaluate('__game.sceneName==="title" && !__edge.world'))
        page.evaluate('__pads[0].buttons[0]={pressed:false,value:0};__game.advance(.1);__pads=[]')
        page.evaluate('__game.menu("settings");__edge.controls.lastActivity=__game.real;__game.advance(10.1)')
        check('idle settings menu also enters attract',page.evaluate('__edge.attract'))
        page.evaluate('__edge.exitAttract();__game.advance(.4)')
        start();page.set_viewport_size({'width':2560,'height':1080});advance(.03)
        point=page.evaluate('''()=>{const g=__game,s=g.screen,o=__edge.art.offset(g.screen);const x=o.x+620,y=o.y+270;return{x:(s.OX+x*s.S)/s.dpr,y:(s.OY+y*s.S)/s.dpr,wx:620,wy:270}}''')
        page.mouse.move(point['x'],point['y']);advance(.03)
        err=page.evaluate('''()=>{const a=__edge,p=a.world.players[0],d=a.controls.read(0,p,a.state),dx=620-p.x,dy=270-p.y,n=Math.hypot(dx,dy);return Math.hypot(d.ax-dx/n,d.ay-dy/n)}''')
        check('mouse target transforms correctly through wide-screen margins',err<.02,err)
        page.set_viewport_size({'width':1200,'height':900});advance(.03)
        check('4:3 view retains the full world and rail',page.evaluate('__game.W>=640 && __game.H>=360'))
        page.set_viewport_size({'width':1920,'height':1080});advance(.03)
        page.evaluate('__edge.dev.jump(2,2);__game.advance(.1);__edge.world.core.timer=.2;__edge.world.step();__edge.syncPresentation(.1)')
        page.evaluate('__game.advance(0,{draw:true})');page.screenshot(animations='disabled',path=str(root/'tests/artifacts/final-heart.png'))
        page.evaluate('''()=>{const w=__edge.world;w.core.mode='flight';w.core.x=350;w.core.y=140;w.hitCore({epoch:w.core.phaseEpoch});for(let i=0;i<100;i++)w.step();__edge.syncPresentation(.8);__game.advance(.01)}''')
        page.evaluate('__game.advance(0,{draw:true})');page.screenshot(animations='disabled',path=str(root/'tests/artifacts/final-explosion.png'))
        page.evaluate('__edge.about()');page.evaluate('__game.advance(0,{draw:true})');page.screenshot(animations='disabled',path=str(root/'tests/artifacts/credits.png'))
        for title in ['Source Information','Testing Feedback','Engine Feedback','Prompt Feedback']:
            page.get_by_role('button',name='Next page',exact=True).click()
            check('credits contain '+title,page.get_by_role('heading',name=title,exact=True).count()==1)
    scenario('attract, geometry and final presentation',geometry_and_attract)

    def authored_visuals():
        start();page.evaluate('''()=>{const a=__edge,w=a.world,b=new Edge.Pilot();for(let i=0;i<120*15&&w.stats.bites<5;i++){w.step(b.actions(w));if(i%2===0)a.art.update(Edge.DT*2,w.snapshot());}a.state=w.snapshot();a.updateHud();__game.advance(0,{draw:true})}''')
        check('ordinary bite approach produces a ready glowing scout',page.evaluate('__edge.world.players[0].charge===5 && !__edge.world.practice'))
        page.screenshot(animations='disabled',path=str(root/'tests/artifacts/bite-charge.png'))
        page.evaluate('''()=>{__edge.startRun();__game.advance(.01);const a=__edge,w=a.world,p=w.players[0];p.x=265;p.y=140;w.core.timer=0;w.step();a.syncPresentation(.2);__game.advance(0,{draw:true})}''')
        page.screenshot(animations='disabled',path=str(root/'tests/artifacts/refuge-swirl.png'))
        page.evaluate('''()=>{const a=__edge;a.startAttract();__game.advance(.01);const w=a.world;for(let i=0;i<120*80&&!w.cannons.some(b=>b.reflected);i++){w.step(a.pilot.actions(w));if(i%2===0)a.art.update(Edge.DT*2,w.snapshot());}a.state=w.snapshot();a.updateHud();__game.advance(0,{draw:true})}''')
        check('reflective showcase uses an actual reflected physical shot',page.evaluate('__edge.world.stats.reflections>0 && __edge.world.cannons.some(b=>b.reflected)'))
        page.screenshot(animations='disabled',path=str(root/'tests/artifacts/reflected-shot.png'))
        page.evaluate('''()=>{const a=__edge;a.startRun();__game.advance(.01);const w=a.world,b=new Edge.Pilot();for(let i=0;i<120*160&&!(w.sector===2&&w.phase===2&&w.core.mode==='flight');i++){w.step(b.actions(w));if(i%2===0)a.art.update(Edge.DT*2,w.snapshot());}window.visualPilot=b;a.state=w.snapshot();a.updateHud();__game.advance(0,{draw:true})}''')
        check('final-battle visual comes from an ordinary full campaign',page.evaluate('__edge.world.sector===2&&__edge.world.phase===2&&__edge.world.core.mode==="flight"&&!__edge.world.practice&&!__edge.world.cheats.invulnerable'))
        page.screenshot(animations='disabled',path=str(root/'tests/artifacts/final-heart.png'))
        page.evaluate('''()=>{const a=__edge,w=a.world;for(let i=0;i<120*40&&w.status!=='collapse';i++){w.step(visualPilot.actions(w));if(i%2===0)a.art.update(Edge.DT*2,w.snapshot());}for(let i=0;i<72;i++){w.step();if(i%2===0)a.art.update(Edge.DT*2,w.snapshot());}a.state=w.snapshot();a.updateHud();__game.advance(0,{draw:true})}''')
        check('final explosion follows a confirmed airborne core kill',page.evaluate('__edge.world.status==="collapse"&&__edge.world.sector===2&&__edge.world.stats.intercepts>0'))
        page.screenshot(animations='disabled',path=str(root/'tests/artifacts/final-explosion.png'))
        page.evaluate('__game.advance(3.2,{draw:true})')
        check('ordinary campaign resolves into the real victory screen and record',page.evaluate('__edge.world.outcome==="victory"&&__edge.ui.screen==="results"&&__edge.records["solo / Normal"]>0'))
        page.get_by_role('button',name='Replay campaign',exact=True).click();advance(.05)
        check('victory replay starts a clean normal campaign',page.evaluate('__edge.world.sector===0&&!__edge.world.practice&&__edge.world.score===0&&__edge.world.reserves===3'))
        page.evaluate('''()=>{const w=__edge.world;w.reserves=0;w.players[0].inv=0;w.kill(w.players[0],'swirl');__game.advance(.03,{draw:true})}''')
        check('total elimination opens the real defeat choices',page.evaluate('__edge.world.outcome==="defeat"&&__edge.ui.screen==="results"') and page.get_by_role('button',name='Retry sector / practice',exact=True).count()==1)
        page.get_by_role('button',name='Retry sector / practice',exact=True).click();advance(.03)
        check('defeat retry is explicitly practice with no stale outcome',page.evaluate('__edge.world.practice&&__edge.world.outcome===null&&__edge.ui.screen===null'))
        saved=page.evaluate('__edge.records["solo / Normal"]')
        page.evaluate('__edge.world.score=999999;__edge.world.outcome="defeat";__edge.world.status="defeat";__edge.flow()')
        check('practice retry cannot overwrite a normal campaign record',page.evaluate('__edge.records["solo / Normal"]')==saved)
        page.evaluate('__edge.ui.hide();__edge.about()');page.screenshot(animations='disabled',path=str(root/'tests/artifacts/credits.png'))
    scenario('authored action and ending visual checks',authored_visuals)

    def audio():
        boot();page.get_by_role('button',name='Solo campaign',exact=True).click();page.wait_for_function('__game.sceneName==="play"');page.evaluate('__game.stop();__edge.sound.unlock()')
        data=page.evaluate('''async()=>{const c=new OfflineAudioContext(1,48000*3,48000);Edge.Sound.offline(c,c.destination);const b=await c.startRendering(),a=b.getChannelData(0);let peak=0,rms=0,tail=0,finite=true;for(let i=0;i<a.length;i++){finite=finite&&Number.isFinite(a[i]);peak=Math.max(peak,Math.abs(a[i]));rms+=a[i]*a[i];if(i>48000*2.8)tail=Math.max(tail,Math.abs(a[i]));}return{finite,peak,rms:Math.sqrt(rms/a.length),tail}}''')
        (root/'tests/artifacts/audio-analysis.json').write_text(json.dumps(data,indent=2))
        check('offline synthesized music/effect/voice output is finite and non-silent',data['finite'] and data['rms']>.005,data)
        check('offline envelopes stay below clipping and end in silence',data['peak']<.8 and data['tail']<.00001,data)
        data=page.evaluate('''()=>{const g=__game;g.settings.set('volume',.4);g.settings.set('music',.2);g.settings.set('effects',.3);g.settings.set('voice',.1);return{master:g.audio.bus('master').gain.value,music:g.audio.bus('music').gain.value,sfx:g.audio.bus('sfx').gain.value,voice:g.audio.bus('voice').gain.value}}''')
        check('master/music/effects/voice settings change actual audio buses',all(abs(data[k]-v)<.001 for k,v in [('master',.4),('music',.2),('sfx',.3),('voice',.1)]),data)
        check('mute closes the actual master bus',page.evaluate('__game.settings.set("sound",false);__game.audio.bus("master").gain.value===0'))
        page.evaluate('__game.settings.set("sound",true);__game.audio.ctx.suspend()')
        page.keyboard.press('j');page.wait_for_timeout(100)
        check('audio resumes after a genuine gesture following suspension',page.evaluate('__game.audio.ctx.state==="running"'))
        page.evaluate('__edge.sound.effect({id:99,type:"collapse",x:550,y:140});__edge.sound.dispose()')
        check('sound disposal stops all custom nodes and mutes output',page.evaluate('__edge.sound.nodes.size===0 && __game.audio.muted'))
    scenario('procedural audio checks',audio)
    check('Chromium artifact has no page/console/game errors',not errors,errors)
    context.close()

    def touch_suite(profile):
        ctx=browser.new_context(**pw.devices[profile]);pg=ctx.new_page();err=[];pg.on('pageerror',lambda e:err.append(str(e)));pg.goto(artifact.as_uri());pg.wait_for_function('window.__game');pg.get_by_role('button',name='Solo campaign',exact=True).tap();pg.wait_for_function('__game.sceneName==="play"');pg.evaluate('__game.stop()');cdp=ctx.new_cdp_session(pg)
        size=pg.viewport_size;w=size['width'];h=size['height'];
        cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':w*.2,'y':h*.66,'id':41},{'x':w*.7,'y':h*.66,'id':42}]})
        cdp.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':w*.2+42,'y':h*.66,'id':41},{'x':w*.7+44,'y':h*.66-8,'id':42}]})
        pg.evaluate('__game.advance(.45,{draw:true})')
        check(profile+' two touches move and fire independently',pg.evaluate('__edge.world.players[0].x>125 && __edge.world.stats.shots>1 && __edge.controls.touch.size===2'))
        check(profile+' native visible stick stays disabled',pg.evaluate('!__game.input.stickOn'))
        cdp.send('Input.dispatchTouchEvent',{'type':'touchCancel','touchPoints':[]});pg.evaluate('__edge.world.players[0].charge=5;__edge.syncPresentation(.01)')
